SELECT t.*, m.category AS category, c.category_name AS category_name,
       m.model_name AS process_name,
       COALESCE(NULLIF(m.model_name, ''), NULLIF(task_procdef.NAME_, '')) AS process_definition_name
FROM sys_flow_task t

LEFT JOIN sys_flow_category c
       ON c.id = m.category
      AND c.tenant_id = #{tenantId}
WHERE t.task_id = #{taskId}
  AND t.tenant_id = #{tenantId}
LIMIT 1

SELECT t.*
FROM sys_flow_task t
WHERE t.task_id = #{taskId}
  AND t.tenant_id = #{tenantId}
FOR UPDATE

mapper.update:
UPDATE sys_flow_task
task_name = #{task.taskName}, task_def_key = #{task.taskDefKey}, task_def_id = #{task.taskDefId}, process_instance_id = #{task.processInstanceId}, process_def_id = #{task.processDefId}, process_def_key = #{task.processDefKey}, business_key = #{task.businessKey}, business_type = #{task.businessType}, title = #{task.title}, assignee = #{task.assignee}, assignee_name = #{task.assigneeName}, candidate_users = #{task.candidateUsers}, candidate_groups = #{task.candidateGroups}, owner = #{task.owner}, due_date = #{task.dueDate}, priority = #{task.priority}, status = #{task.status}, comment = #{task.comment}, signature = #{task.signature}, attachment_urls = #{task.attachmentUrls}, start_user_id = #{task.startUserId}, start_user_name = #{task.startUserName}, start_dept_id = #{task.startDeptId}, start_dept_name = #{task.startDeptName}, claim_time = #{task.claimTime}, complete_time = #{task.completeTime}, action_idempotency_key = #{task.actionIdempotencyKey}, action_request_digest = #{task.actionRequestDigest}, action_type = #{task.actionType},
WHERE task_id = #{taskId} AND tenant_id = #{tenantId}

mapper.select:
SELECT COUNT(1)
FROM sys_flow_task t
WHERE t.process_instance_id = #{processInstanceId}
  AND t.tenant_id = #{tenantId}
  AND (t.assignee = #{userId} OR t.owner = #{userId} OR t.start_user_id = #{userId}
       OR EXISTS (
           SELECT 1
           FROM sys_flow_task_candidate tc
           WHERE tc.tenant_id = t.tenant_id
             AND tc.task_id = t.task_id
             AND tc.candidate_type = 'USER'
             AND tc.candidate_value = #{userId}
             AND tc.status = 1
       )
       OR FIND_IN_SET(#{userId}, candidate_users) > 0)

SELECT t.*
FROM sys_flow_task t
WHERE t.process_instance_id = #{processInstanceId}
  AND t.tenant_id = #{tenantId}
ORDER BY t.create_time ASC, t.id ASC

SELECT t.id, t.tenant_id, t.task_id, t.process_instance_id, t.process_def_id, t.process_def_key, t.task_def_key, t.due_date, t.status, t.create_time FROM sys_flow_task t WHERE t.due_date IS NOT NULL AND t.due_date <= #{now} AND t.status IN (0, 1)
AND ( t.due_date > #{cursorDueDate} OR (t.due_date = #{cursorDueDate} AND t.id > #{cursorId}) )
ORDER BY t.due_date ASC, t.id ASC LIMIT #{limit}

SELECT t.id, t.tenant_id, t.task_id, t.process_instance_id, t.process_def_id, t.process_def_key, t.task_def_key, t.create_time, t.status FROM sys_flow_task t WHERE t.due_date IS NULL AND t.create_time IS NOT NULL AND t.create_time <= #{now} AND t.status IN (0, 1)
AND ( t.create_time > #{cursorCreateTime} OR (t.create_time = #{cursorCreateTime} AND t.id > #{cursorId}) )
ORDER BY t.create_time ASC, t.id ASC LIMIT #{limit}

