mapper.sql:
AND ( t.assignee = #{userId} OR EXISTS ( SELECT 1 FROM sys_flow_task_candidate tc WHERE tc.tenant_id = t.tenant_id AND tc.task_id = t.task_id AND tc.candidate_type = 'USER' AND tc.candidate_value = #{userId} AND tc.status = 1 )
OR EXISTS ( SELECT 1 FROM sys_flow_task_candidate tc WHERE tc.tenant_id = t.tenant_id AND tc.task_id = t.task_id AND tc.candidate_type = 'GROUP' AND tc.status = 1 AND tc.candidate_value IN
#{groupValue}
)
OR ( NOT EXISTS ( SELECT 1 FROM sys_flow_task_candidate normalized_candidate WHERE normalized_candidate.tenant_id = t.tenant_id AND normalized_candidate.task_id = t.task_id ) AND ( ( t.candidate_users IS NOT NULL AND t.candidate_users != '' AND FIND_IN_SET( REPLACE(REPLACE(REPLACE(REPLACE(#{userId}, ';', ','), '；', ','), '，', ','), ' ', ''), REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(t.candidate_users, ';', ','), '；', ','), '，', ','), '、', ','), ' ', '') ) > 0 )
OR ( t.candidate_groups IS NOT NULL AND t.candidate_groups != '' AND (
FIND_IN_SET( #{groupValue}, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(t.candidate_groups, ';', ','), '；', ','), '，', ','), '、', ','), ' ', '') ) > 0
) )
) ) )

mapper.select:
SELECT 
FROM sys_flow_task t


    AND t.tenant_id = #{tenantId}


    AND (t.status = 0 OR (t.assignee = #{userId} AND t.status = 1))

        AND t.title LIKE CONCAT('%', #{title}, '%')


        AND (
            m.category = #{category}
            OR EXISTS (
                SELECT 1
                FROM sys_flow_category fc
                JOIN sys_flow_category selected
                  ON selected.tenant_id = #{tenantId}
                 AND (selected.id = #{category} OR selected.category_code = #{category})
                WHERE fc.tenant_id = #{tenantId}
                  AND (fc.id = m.category OR fc.category_code = m.category)
                  AND (fc.id = selected.id OR fc.ancestors LIKE CONCAT('%', selected.id, '/%'))
            )
        )


        AND t.status = #{status}


ORDER BY t.create_time DESC

SELECT 
FROM sys_flow_task t


    AND t.tenant_id = #{tenantId}
    AND t.assignee = #{userId}
    AND t.status IN (2, 3, 4, 5, 7, 8)

        AND t.title LIKE CONCAT('%', #{title}, '%')


        AND (
            m.category = #{category}
            OR EXISTS (
                SELECT 1
                FROM sys_flow_category fc
                JOIN sys_flow_category selected
                  ON selected.tenant_id = #{tenantId}
                 AND (selected.id = #{category} OR selected.category_code = #{category})
                WHERE fc.tenant_id = #{tenantId}
                  AND (fc.id = m.category OR fc.category_code = m.category)
                  AND (fc.id = selected.id OR fc.ancestors LIKE CONCAT('%', selected.id, '/%'))
            )
        )


        AND t.status = #{status}


ORDER BY t.complete_time DESC

SELECT 
FROM sys_flow_task t


    AND t.tenant_id = #{tenantId}
    AND t.start_user_id = #{userId}

        AND t.title LIKE CONCAT('%', #{title}, '%')


        AND (
            m.category = #{category}
            OR EXISTS (
                SELECT 1
                FROM sys_flow_category fc
                JOIN sys_flow_category selected
                  ON selected.tenant_id = #{tenantId}
                 AND (selected.id = #{category} OR selected.category_code = #{category})
                WHERE fc.tenant_id = #{tenantId}
                  AND (fc.id = m.category OR fc.category_code = m.category)
                  AND (fc.id = selected.id OR fc.ancestors LIKE CONCAT('%', selected.id, '/%'))
            )
        )


        AND t.status = #{status}


ORDER BY t.create_time DESC

SELECT COUNT(1)
FROM sys_flow_task t
WHERE t.tenant_id = #{tenantId}
  AND t.due_date IS NOT NULL
  AND t.due_date <= #{now}
  AND t.status IN (0, 1)

SELECT COUNT(1)
FROM sys_flow_task t
WHERE t.tenant_id = #{tenantId}
  AND t.assignee = #{userId}
  AND t.status IN (2, 3, 4, 5, 7, 8)
  AND t.complete_time >= #{since}

SELECT COUNT(1)
FROM sys_flow_task t
WHERE t.tenant_id = #{tenantId}
  AND t.start_user_id = #{userId}
  AND t.status IN (0, 1)

